import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.concurrent.Executors;

public class HttpServer {
  public static void main(String[] args) throws Exception {
    // One virtual thread per task: the JVM creates a heap object
    // thread that blocks on I/O by parking its continuation. A few
    // dozen carrier threads multiplex hundreds of thousands of
    // virtual threads, so concurrency is no longer capped by OS
    // threads.
    try (var pool = Executors.newVirtualThreadPerTaskExecutor()) {
      var client = HttpClient.newHttpClient();
      for (int i = 0; i < 10_000; i++) {
        pool.submit(() -> {
          HttpRequest req =
              HttpRequest.newBuilder(URI.create("https://example.com")).build();
          try {
            HttpResponse<String> res =
                client.send(req, HttpResponse.BodyHandlers.ofString());
            System.out.println("response " + res.statusCode());
          } catch (Exception e) {
            System.out.println("request failed: " + e);
          }
        });
      }
    }
  }
}
